/* Teacher planner extension. Existing v1 records remain compatible. */
Planner.normalize(state);
const oldPersist=persist;persist=function(){Planner.normalize(state);return oldPersist();};
const oldBackupValidation=validateBackup;validateBackup=function(data){return oldBackupValidation(data)&&Planner.validateExtras(data);};
menus.splice(3,0,['timetable','주간 시간표','calendar']);
let taskCategory='',taskStatus='open';
const categoryColor=name=>state.categories.find(c=>c.name===name)?.color||'slate';
const tag=(name,color)=>`<span class="tag tone-${esc(color)}"><i></i>${esc(name)}</span>`;
const oldFields=fields;fields=function(type){const fs=oldFields(type);if(type==='tasks')return fs.map(f=>f[0]==='category'?['category','카테고리',state.categories.map(c=>c.name)]:f[0]==='date'?['date','마감일','date']:f);return fs;};
const oldRenderContent=renderContent;renderContent=function(){if(page==='timetable')$('#content').innerHTML=timetableView();else oldRenderContent();};
taskRow=function(t){return `<div class="task-row ${t.done?'done':''}"><input type="checkbox" aria-label="${esc(t.title)} 완료" data-task="${t.id}" ${t.done?'checked':''}><span class="task-title">${esc(t.title)}</span>${tag(t.category,categoryColor(t.category))}</div>`;};
const oldDashboard=dashboard;dashboard=function(){let html=oldDashboard();const marker='<section class="card"><div class="card-head"><h2>'+icon('calendar')+'오늘의 일정';const start=html.indexOf(marker);if(start>=0){const end=html.indexOf('</section>',start)+10;const events=Planner.eventsForDate(state,today()).filter(e=>match(e.title,e.place));const body=events.slice(0,5).map(e=>`<div class="timeline-row"><span class="timeline-time">${esc(e.time)}</span><span class="timeline-line ${e.recurring?'repeat-line':''}"></span><div class="timeline-copy">${esc(e.title)}<small>${e.recurring?`${esc(e.period)} · 시간표`:'개별 일정'}${e.place?' · '+esc(e.place):''}</small></div>${e.recurring?'<span class="mini-label">매주</span>':''}</div>`).join('');html=html.slice(0,start)+`<section class="card"><div class="card-head"><h2>${icon('calendar')}오늘의 일정 <span class="badge">${events.length}</span></h2><button class="text-btn" data-page="events">전체 보기 ${icon('arrow')}</button></div>${body||empty('오늘 등록된 일정이 없어요.','<button class="btn" data-page="timetable">주간 시간표 등록</button>')}${events.length>5?`<p class="small muted">이외 ${events.length-5}개 일정이 있어요.</p>`:''}</section>`+html.slice(end);}
return html.replace('오늘의 작은 기록, 더 여유로운 내일.','오늘 수업부터 챙길 일까지, 한눈에.').replace('챙길 일은 이곳에 두고, 학생들과의 시간에 집중하세요.','주간 시간표는 오늘 일정에 자동으로 들어와요.');};
tasksView=function(){if(taskCategory&&!state.categories.some(c=>c.name===taskCategory))taskCategory='';const all=state.tasks.filter(t=>match(t.title,t.category)&&(!taskCategory||t.category===taskCategory)),remaining=all.filter(t=>!t.done).length,completed=all.length-remaining;const rows=all.filter(t=>(!taskCategory||t.category===taskCategory)&&(taskStatus==='all'||(taskStatus==='done'?t.done:!t.done))).sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date));return heading('할 일마다, 알맞은 자리를.','카테고리로 나누고, 지금 필요한 일부터 확인하세요.',addBtn('할 일 추가','tasks'))+`<div class="task-workspace"><div class="category-panel"><div class="category-head"><h2>카테고리</h2><button class="text-btn" data-action="category-manager" aria-label="카테고리 관리">${icon('settings')}</button></div><button class="category-item ${!taskCategory?'selected':''}" data-category="" aria-pressed="${!taskCategory}"><span class="category-dot tone-slate"></span>전체 할 일<span>${state.tasks.filter(t=>!t.done).length}</span></button>${state.categories.map(c=>`<button class="category-item ${taskCategory===c.name?'selected':''}" data-category="${esc(c.name)}" aria-pressed="${taskCategory===c.name}"><span class="category-dot tone-${esc(c.color)}"></span>${esc(c.name)}<span>${state.tasks.filter(t=>t.category===c.name&&!t.done).length}</span></button>`).join('')}<button class="category-add" data-action="category-new">${icon('plus')}카테고리 추가</button><div class="category-tip">카테고리 옆 숫자는<br>아직 남은 할 일이에요.</div></div><section class="task-board"><div class="task-board-top"><div><h2>${esc(taskCategory||'전체 할 일')}</h2><p class="sub">남은 일 ${remaining}개 · 완료 ${completed}개</p></div><div class="segmented" aria-label="완료 상태 필터">${[['open','미완료'],['done','완료'],['all','전체']].map(([v,l])=>`<button data-task-status="${v}" aria-pressed="${taskStatus===v}" class="${taskStatus===v?'active':''}">${l}</button>`).join('')}</div></div>${rows.map(t=>`<article class="task-item ${t.done?'is-done':''}"><div class="task-item-body">${taskRow(t)}<span class="task-due ${!t.done&&t.date<today()?'overdue':''}">${icon('calendar')}${esc(t.date)}${!t.done&&t.date<today()?' · 기한 지남':t.date===today()?' · 오늘':''}</span></div>${actions('tasks',t.id)}</article>`).join('')||empty(filter?'검색 결과가 없어요.':taskStatus==='done'?'완료한 일이 아직 없어요.':'이곳의 할 일을 모두 챙겼어요.',addBtn('할 일 추가','tasks'))}</section></div>`;};
function weekDates(date){const day=new Date(date+'T12:00:00').getDay(),monday=Planner.datePlus(date,-((day+6)%7));return Array.from({length:7},(_,i)=>Planner.datePlus(monday,i));}
function scheduleRow(e){return `<article class="schedule-row ${e.skipped?'skipped':''}"><div class="schedule-time"><b>${esc(e.time)}</b>${e.end?`<small>${esc(e.end)}</small>`:''}</div><div class="schedule-card ${e.recurring?'lesson-card':'event-card'} tone-${esc(e.color||'slate')}"><div class="schedule-main"><div class="schedule-labels">${tag(e.recurring?e.period+' · 시간표':'개별 일정',e.recurring?e.color:'slate')}${e.skipped?'<span class="badge orange">이 날짜 제외</span>':''}</div><h3>${esc(e.title)}</h3>${e.place?`<p>${esc(e.place)}</p>`:''}</div><div class="actions">${e.recurring?`<button data-action="lesson-edit" data-id="${e.id}" aria-label="${esc(e.title)} 주간 수업 수정">${icon('edit')}</button><button class="skip-btn" data-action="lesson-skip" data-id="${e.id}">${e.skipped?'다시 표시':'오늘만 제외'}</button>`:actions('events',e.id)}</div></div></article>`;}
eventView=function(){const events=Planner.eventsForDate(state,selectedDate,true).filter(e=>match(e.title,e.place)),active=events.filter(e=>!e.skipped),recurring=active.filter(e=>e.recurring).length;const off=state.planner.offDates.includes(selectedDate);return heading('수업과 일정을, 한 흐름으로.','등록한 주간 시간표가 요일에 맞춰 자동으로 표시됩니다.',`<div class="heading-actions"><button class="btn" data-page="timetable">${icon('calendar')}시간표 편집</button>${addBtn('개별 일정','events')}</div>`)+`<div class="planner-layout"><section><div class="calendar-card"><div class="calendar-controls"><div><button class="icon-btn" data-action="week-prev" aria-label="이전 주">‹</button><b>${esc(weekDates(selectedDate)[0].replaceAll('-','.'))} – ${esc(weekDates(selectedDate)[6].slice(5).replace('-','.'))}</b><button class="icon-btn" data-action="week-next" aria-label="다음 주">›</button></div><button class="btn" data-action="today">오늘</button></div><div class="week-strip">${weekDates(selectedDate).map((d,i)=>`<button data-schedule-date="${d}" aria-pressed="${d===selectedDate}" class="${d===selectedDate?'selected':''} ${d===today()?'is-today':''}"><small>${['월','화','수','목','금','토','일'][i]}</small><b>${Number(d.slice(8))}</b><span class="day-dot ${Planner.eventsForDate(state,d).length?'has-events':''}"></span></button>`).join('')}</div></div><div class="daily-heading"><div><p class="eyebrow">DAILY SCHEDULE</p><h2>${dateText(selectedDate)}</h2></div><span class="sub">수업 ${recurring}개 · 개별 일정 ${active.length-recurring}개</span></div><div class="schedule-list">${events.map(scheduleRow).join('')||empty('이 날짜에는 등록된 일정이 없어요.','<button class="btn" data-page="timetable">주간 시간표 등록하기</button>')}</div></section><div class="planner-side"><section class="card"><div class="card-head"><h2>${icon('calendar')}날짜 선택</h2></div><label class="field">확인할 날짜<input id="date-select" aria-label="일정 날짜" type="date" value="${selectedDate}"></label><button class="btn ${off?'primary':''}" style="width:100%" data-action="day-off">${off?'이 날짜 수업 다시 표시':'이 날짜 수업 모두 제외'}</button><p class="small muted">휴업일에는 시간표 수업만 제외해요. 개별 일정은 그대로 표시됩니다.</p></section><section class="card auto-info"><span class="auto-icon">${icon('check')}</span><h2>한 번 등록하면 매주 자동으로</h2><p>주간 시간표의 수업이 해당 요일에 표시돼요. 같은 수업이 중복으로 추가되지 않아요.</p><button class="text-btn" data-page="timetable">주간 시간표 열기 ${icon('arrow')}</button></section></div></div>`;};
function timetableView(){const p=state.planner,count=p.lessons.length;return heading('우리 반의 한 주를 그려요.','빈칸을 눌러 수업을 등록하세요. 학급 일정에 매주 자동으로 표시돼요.',`<div class="heading-actions"><button class="btn" data-action="period-settings">${icon('clock')}교시 · 적용 기간</button><button class="btn primary" data-page="events">일정에서 보기 ${icon('arrow')}</button></div>`)+`<div class="timetable-banner"><span class="auto-icon">${icon('check')}</span><div><b>매주 반복되는 수업 ${count}개</b><p>${p.startDate||p.endDate?`${esc(p.startDate||'시작 제한 없음')} ~ ${esc(p.endDate||'종료 제한 없음')} 적용`:'월요일부터 금요일까지 반복 · 적용 기간 제한 없음'}</p></div><span class="live-pill">일정에 자동 반영</span></div><div class="table-wrap timetable-wrap"><table class="timetable"><thead><tr><th>교시 / 시간</th>${['월요일','화요일','수요일','목요일','금요일'].map((day,i)=>`<th class="${new Date().getDay()===i+1?'current-day':''}">${day}</th>`).join('')}</tr></thead><tbody>${p.periods.map(period=>`<tr><th scope="row"><b>${esc(period.name)}</b><small>${esc(period.start)} – ${esc(period.end)}</small></th>${[1,2,3,4,5].map(day=>{const l=p.lessons.find(x=>x.day===day&&x.periodId===period.id),hidden=l&&!match(l.subject,l.place);return `<td><button class="lesson-cell ${l?'filled tone-'+esc(l.color):''} ${hidden?'search-dim':''}" data-action="lesson-cell" data-period="${period.id}" data-day="${day}" aria-label="${['','월요일','화요일','수요일','목요일','금요일'][day]} ${esc(period.name)} ${l?esc(l.subject)+' 수정':'수업 추가'}">${l?`<b>${esc(l.subject)}</b><small>${esc(l.place||'장소 미지정')}</small><span class="cell-edit">${icon('edit')}</span>`:`<span class="cell-plus">+</span><small>수업 추가</small>`}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="timetable-foot"><span>${icon('note')}수업을 수정하면 해당 요일의 일정도 함께 바뀝니다.</span><span>특정 날짜만 쉬려면 ‘학급 일정’에서 제외해 주세요.</span></div>`;}
function customModal(title,body,onSave){$('#modal').innerHTML=`<form id="planner-form"><div class="modal-head"><h2>${esc(title)}</h2><button type="button" class="text-btn" data-action="close" aria-label="닫기">${icon('close')}</button></div>${body}<p id="form-error" class="form-error" role="alert"></p><div class="modal-foot"><button type="button" class="btn" data-action="close">취소</button><button class="btn primary" type="submit">저장하기</button></div></form>`;$('#planner-form').onsubmit=e=>{e.preventDefault();if(onSave(Object.fromEntries(new FormData(e.target)))!==false){persist();$('#modal').close();renderContent();toast('저장했어요.');}};if(!$('#modal').open)$('#modal').showModal();}
function formError(text){$('#form-error').textContent=text;return false;}
function colorPicker(value){return `<fieldset class="color-picker"><legend>구분 색상</legend>${Planner.colors.map((c,i)=>`<label class="tone-${c}"><input type="radio" name="color" value="${c}" ${c===value?'checked':''} aria-label="${['초록','파랑','노랑','분홍','보라','회색'][i]}"><span></span></label>`).join('')}</fieldset>`;}
function editLesson(day,periodId){const p=state.planner,period=p.periods.find(x=>x.id===periodId),lesson=p.lessons.find(l=>l.day===day&&l.periodId===periodId);if(!period)return;customModal(`${['','월요일','화요일','수요일','목요일','금요일'][day]} · ${period.name}`,`<p class="sub">매주 ${['','월','화','수','목','금'][day]}요일 ${esc(period.start)} – ${esc(period.end)} 일정에 표시됩니다.</p><label class="field">수업 이름<input name="subject" required maxlength="80" placeholder="예: 국어, 생활 속 수학" value="${esc(lesson?.subject||'')}"></label><label class="field">장소 (선택)<input name="place" maxlength="100" placeholder="예: 우리 반 교실" value="${esc(lesson?.place||'')}"></label>${colorPicker(lesson?.color||Planner.colors[(day-1)%5])}${lesson?`<button type="button" class="text-btn danger-text" data-action="lesson-remove" data-id="${lesson.id}">${icon('trash')}이 주간 수업 삭제</button>`:''}`,data=>{const subject=data.subject.trim();if(!subject)return formError('수업 이름을 입력해 주세요.');if(lesson)Object.assign(lesson,{subject,place:data.place.trim(),color:data.color});else p.lessons.push({id:uid(),day,periodId,subject,place:data.place.trim(),color:data.color});});}
function editCategory(id=''){const c=state.categories.find(x=>x.id===id);customModal(c?'카테고리 수정':'새 카테고리',`<label class="field">카테고리 이름<input name="name" required maxlength="30" placeholder="예: 개별화교육, 체험학습" value="${esc(c?.name||'')}"></label>${colorPicker(c?.color||'sage')}`,data=>{const name=data.name.trim();if(!name)return formError('카테고리 이름을 입력해 주세요.');if(state.categories.some(x=>x.id!==id&&x.name===name))return formError('같은 이름의 카테고리가 이미 있어요.');if(c){const old=c.name;state.tasks.forEach(t=>{if(t.category===old)t.category=name;});if(taskCategory===old)taskCategory=name;Object.assign(c,{name,color:data.color});}else state.categories.push({id:uid(),name,color:data.color});});}
function categoryManager(){const body=state.categories.map(c=>`<div class="category-manage-row">${tag(c.name,c.color)}<div class="actions"><button data-action="category-edit" data-id="${c.id}" aria-label="${esc(c.name)} 수정">${icon('edit')}</button><button data-action="category-remove" data-id="${c.id}" aria-label="${esc(c.name)} 삭제" ${c.name==='기타'?'disabled':''}>${icon('trash')}</button></div></div>`).join('');$('#modal').innerHTML=`<div class="modal-head"><h2>카테고리 관리</h2><button class="text-btn" data-action="close" aria-label="닫기">${icon('close')}</button></div><p class="sub">이름과 색상을 바꿀 수 있어요.<br>삭제한 카테고리의 할 일은 ‘기타’로 옮겨집니다.</p>${body}<div class="modal-foot"><button class="btn primary" data-action="category-new">${icon('plus')}카테고리 추가</button><button class="btn" data-action="close">닫기</button></div>`;if(!$('#modal').open)$('#modal').showModal();}
function periodSettings(){const p=state.planner;let draft=structuredClone(p.periods),rangeDraft={startDate:p.startDate,endDate:p.endDate};const render=()=>{customModal('교시와 적용 기간',`<p class="sub">우리 학교 시간에 맞게 바꿔 주세요. 교시를 삭제하면 해당 교시의 주간 수업도 삭제됩니다.</p><div class="period-editor">${draft.map((r,i)=>`<div class="period-edit-row"><label class="field">교시 이름<input name="name-${r.id}" required maxlength="30" value="${esc(r.name)}"></label><label class="field">시작<input type="time" name="start-${r.id}" required value="${r.start}"></label><label class="field">종료<input type="time" name="end-${r.id}" required value="${r.end}"></label><button type="button" class="icon-btn" data-period-remove="${r.id}" aria-label="${esc(r.name)} 삭제" ${draft.length<=1?'disabled':''}>${icon('trash')}</button></div>`).join('')}</div><button class="btn" type="button" id="add-period" ${draft.length>=12?'disabled':''}>${icon('plus')}교시 추가</button><div class="date-range"><label class="field">적용 시작일 (선택)<input type="date" name="startDate" value="${esc(p.startDate)}"></label><label class="field">적용 종료일 (선택)<input type="date" name="endDate" value="${esc(p.endDate)}"></label></div><p class="small muted">기간을 비워 두면 매주 계속 표시됩니다. 최대 12교시까지 등록할 수 있어요.</p>`,data=>{const periods=draft.map(r=>({id:r.id,name:data['name-'+r.id].trim(),start:data['start-'+r.id],end:data['end-'+r.id]}));if(periods.some(r=>!r.name||r.start>=r.end))return formError('교시 이름과 시간을 확인해 주세요. 종료는 시작보다 늦어야 해요.');if(data.startDate&&data.endDate&&data.startDate>data.endDate)return formError('종료일은 시작일보다 빠를 수 없어요.');periods.sort((a,b)=>a.start.localeCompare(b.start));if(periods.some((r,i)=>i&&periods[i-1].end>r.start))return formError('교시 시간이 서로 겹칩니다. 시작·종료 시간을 확인해 주세요.');p.periods=periods;p.lessons=p.lessons.filter(l=>periods.some(r=>r.id===l.periodId));p.startDate=data.startDate;p.endDate=data.endDate;});const capture=()=>{const data=Object.fromEntries(new FormData($('#planner-form')));draft=draft.map(r=>({id:r.id,name:data['name-'+r.id],start:data['start-'+r.id],end:data['end-'+r.id]}));rangeDraft={startDate:data.startDate,endDate:data.endDate};};const restoreDates=()=>{$('#planner-form [name=startDate]').value=rangeDraft.startDate;$('#planner-form [name=endDate]').value=rangeDraft.endDate;};$('#add-period').onclick=()=>{capture();const last=draft[draft.length-1],time=last?.end||'14:30';let minutes=Number(time.slice(0,2))*60+Number(time.slice(3))+10;minutes=Math.min(minutes,23*60);const asTime=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');draft.push({id:uid(),name:(draft.length+1)+'교시',start:asTime(minutes),end:asTime(Math.min(minutes+40,1439))});render();restoreDates();};$$('[data-period-remove]').forEach(b=>b.onclick=()=>{capture();draft=draft.filter(r=>r.id!==b.dataset.periodRemove);render();restoreDates();});};render();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.category!==undefined){taskCategory=d.category;renderContent();}if(d.taskStatus){taskStatus=d.taskStatus;renderContent();}if(d.scheduleDate){selectedDate=d.scheduleDate;renderContent();}switch(d.action){case'week-prev':selectedDate=Planner.datePlus(selectedDate,-7);renderContent();break;case'week-next':selectedDate=Planner.datePlus(selectedDate,7);renderContent();break;case'lesson-cell':editLesson(Number(d.day),d.period);break;case'lesson-edit':{const l=state.planner.lessons.find(x=>x.id===d.id);if(l)editLesson(l.day,l.periodId);break;}case'lesson-remove':confirmBox('주간 수업 삭제','이 수업을 모든 요일별 일정에서 삭제할까요?',()=>{state.planner.lessons=state.planner.lessons.filter(l=>l.id!==d.id);persist();renderContent();toast('주간 수업을 삭제했어요.');});break;case'lesson-skip':{if(state.planner.offDates.includes(selectedDate)){toast('이 날짜의 수업 전체가 제외되어 있어요. 오른쪽에서 다시 표시해 주세요.');break;}const key=selectedDate+'|'+d.id,p=state.planner;p.skips=p.skips.includes(key)?p.skips.filter(x=>x!==key):[...p.skips,key];persist();renderContent();break;}case'day-off':{const p=state.planner;p.offDates=p.offDates.includes(selectedDate)?p.offDates.filter(d=>d!==selectedDate):[...p.offDates,selectedDate];persist();renderContent();toast(p.offDates.includes(selectedDate)?'이 날짜의 시간표 수업을 제외했어요.':'이 날짜의 시간표 수업을 다시 표시해요.');break;}case'period-settings':periodSettings();break;case'category-manager':categoryManager();break;case'category-new':editCategory();break;case'category-edit':editCategory(d.id);break;case'category-remove':{const c=state.categories.find(x=>x.id===d.id);if(!c||c.name==='기타')break;confirmBox('카테고리 삭제',`‘${c.name}’의 할 일은 ‘기타’로 옮깁니다. 삭제할까요?`,()=>{if(!state.categories.some(c=>c.name==='기타'))state.categories.push({id:uid(),name:'기타',color:'slate'});state.tasks.forEach(t=>{if(t.category===c.name)t.category='기타';});state.categories=state.categories.filter(x=>x.id!==c.id);if(taskCategory===c.name)taskCategory='';persist();renderContent();toast('카테고리를 정리했어요.');});break;}}});
const previousOpenForm=openForm;
openForm=function(type,id='',student=''){previousOpenForm(type,id,student);if(type==='tasks'&&!id&&taskCategory){const select=$('#record-form [name=category]');if(select)select.value=taskCategory;}};
persist();shell();
